//! `contract/golden/idea_similarity.json` is what the Python `services/idea_similarity.py` computes (generated by
//! `contract/golden/gen_idea_similarity.py`): the words of a text, the unrounded cosine score of each candidate, and
//! the ranked result. The Rust scores must be the same bit for bit.

use kb_ideas::idea_similarity::{Candidate, rank, scores, words};
use serde_json::{Map, Value, json};

fn golden() -> Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../contract/golden/idea_similarity.json");
    serde_json::from_str(&std::fs::read_to_string(path).expect("golden file idea_similarity.json exists"))
        .expect("parses")
}

#[test]
fn the_words_of_a_text_are_the_ones_python_finds() {
    let golden = golden();
    let cases = golden["words"].as_array().expect("words");
    assert!(cases.len() > 200, "{} cases", cases.len());
    for case in cases {
        let text = case["text"].as_str().expect("text");
        let expected: Vec<&str> =
            case["words"].as_array().expect("words").iter().map(|w| w.as_str().expect("w")).collect();
        assert_eq!(words(text), expected, "{text:?}");
    }
}

fn candidates(case: &Value) -> Vec<Candidate> {
    case["candidates"]
        .as_array()
        .expect("candidates")
        .iter()
        .map(|c| {
            let mut fields = Map::new();
            fields.insert("id".into(), c["id"].clone());
            Candidate { text: c["text"].as_str().expect("text").to_string(), fields }
        })
        .collect()
}

#[test]
fn the_scores_are_python_s_bit_for_bit() {
    let golden = golden();
    let cases = golden["rank"].as_array().expect("rank");
    assert!(cases.len() >= 300, "{} cases", cases.len());
    let mut compared = 0;
    for case in cases {
        let query = case["query"].as_str().expect("query");
        let cands = candidates(case);
        let got = scores(query, &cands);
        for ((got, expected), cand) in got.iter().zip(case["candidates"].as_array().expect("c")).zip(&cands) {
            let expected = expected["raw"].as_f64().expect("raw");
            assert_eq!(got.to_bits(), expected.to_bits(), "{query:?} against {:?}: {got} != {expected}", cand.text);
            compared += 1;
        }
    }
    assert!(compared > 1000, "{compared} scores compared");
}

#[test]
fn the_ranked_result_is_python_s() {
    let golden = golden();
    for case in golden["rank"].as_array().expect("rank") {
        let query = case["query"].as_str().expect("query");
        let min_score = case["min_score"].as_f64().expect("min_score");
        let got: Vec<Value> = rank(query, &candidates(case), min_score)
            .into_iter()
            .map(|item| json!({"id": item["id"], "score": item["score"]}))
            .collect();
        assert_eq!(Value::Array(got), case["result"], "{query:?} (min {min_score})");
    }
}
